package cn.richie696.component.secret.provider.pkcs11;
import cn.richie696.component.secret.bootstrap.*; import cn.richie696.component.secret.starter.SecretRuntimeAutoConfiguration; import org.springframework.boot.autoconfigure.*; import org.springframework.boot.autoconfigure.condition.*; import org.springframework.context.annotation.Bean;
@AutoConfiguration @AutoConfigureBefore(SecretRuntimeAutoConfiguration.class) @ConditionalOnProperty(prefix=BootstrapSecretProperties.PREFIX,name="enabled",havingValue="true") public class Pkcs11SecretAutoConfiguration { @Bean(destroyMethod="close") @ConditionalOnBean(SecretBootstrapState.class) @ConditionalOnMissingBean(Pkcs11SecretClient.class) Pkcs11SecretClient pkcs11SecretClient(SecretBootstrapState state){if(!(state.client() instanceof Pkcs11SecretClient c))throw new IllegalStateException("PKCS#11 bootstrap client is not available");return c;} }
